import assert from'node:assert/strict';
/** Source-reviewed geometry and labels, independent from production model. */
export const businessReviewedEmploymentAlt='企業Aと企業Bを横に置き，下に労働者Cを置く。企業Aと企業Bの間は両端に矢印がある線で結ばれ，「“契約”」と記す。企業Aと労働者Cの間も両端に矢印がある線で結ばれ，「雇用関係」と記す。企業Bと労働者Cの間は両端に矢印がある線で結ばれ，関係名は記されていない。';
const attr=(s:string,k:string)=>{const m=s.match(new RegExp(`(?:^|\\s)${k}="([^"]*)"`));assert(m,k+' missing');return m[1];};
export function readBusinessEmploymentSvg(svg:string){assert.match(svg,/viewBox="0 0 900 300"/);const boxes=[...svg.matchAll(/<rect ([^>]+)>/g)];assert.deepEqual(boxes.map(m=>['data-employment-box','x','y','width','height'].map(k=>attr(m[1],k))),[['A','190','30','160','55'],['B','540','30','160','55'],['C','365','190','160','55']]);const marker=svg.match(/<marker ([^>]+)>(.*?)<\/marker>/);assert(marker);assert.equal(attr(marker[1],'orient'),'auto-start-reverse');assert.equal(attr(marker[1],'markerUnits'),'userSpaceOnUse');assert.deepEqual(['markerWidth','markerHeight','refX','refY'].map(k=>attr(marker[1],k)),['12','12','10','6']);const markerId=attr(marker[1],'id'),path=marker[2].match(/<path ([^>]+)>/);assert(path);assert.equal(attr(path[1],'d'),'M 1 1 L 10 6 L 1 11');assert.equal(attr(path[1],'stroke'),'currentColor');assert.equal(attr(path[1],'fill'),'none');assert.equal(attr(path[1],'stroke-width'),'2');const edges=[...svg.matchAll(/<path ([^>]*data-employment-edge=[^>]+)>/g)];assert.equal(edges.length,3);const expected=[['AB','M 350 58 L 540 58'],['AC','M 270 85 L 445 190'],['BC','M 620 85 L 445 190']];edges.forEach((m,i)=>{assert.deepEqual([attr(m[1],'data-employment-edge'),attr(m[1],'d')],expected[i]);assert.equal(attr(m[1],'marker-start'),`url(#${markerId})`);assert.equal(attr(m[1],'marker-end'),`url(#${markerId})`);});const labels=[...svg.matchAll(/<text ([^>]+)>(.*?)<\/text>/g)];assert.deepEqual(labels.map(m=>[attr(m[1],'data-employment-label'),attr(m[1],'x'),attr(m[1],'y'),m[2]]),[['A','270','65','企業A'],['B','620','65','企業B'],['C','445','225','労働者C'],['AB','445','43','“契約”'],['AC','298','158','雇用関係']]);assert.equal(svg.match(/<desc[^>]*>(.*?)<\/desc>/)?.[1],businessReviewedEmploymentAlt);return{boxes:3,edges:3,heads:6,labelGroups:5,glyphs:labels.reduce((s,m)=>s+[...m[2]].length,0),labels:labels.map(m=>m[2])};}
